class CelestialBody {
public:
    std::string name;
    float mass;
    Vector3 position;
    Vector3 velocity;
    Vector3 acceleration;
    Vector3 force;
    Vector3 gravitational_force;

    CelestialBody(std::string name, float mass, Vector3 position, Vector3 velocity)
        : name(name), mass(mass), position(position), velocity(velocity) {}

    void update(float deltaTime, const std::vector<std::shared_ptr<CelestialBody>>& bodies) {
        // Newton's inverse cube law: F = G * (m1 * m2) / r^3
        const float G = 6.674e-11; // Universal gravitational constant

        force = Vector3(0.0f, 0.0f, 0.0f);

        for (const auto& other : bodies) {
            if (other.get() != this) {
                float distance = position.length() - other->position.length(); // Simplified distance calculation
                float distanceCubed = distance * distance * distance;
                float forceMagnitude = (G * mass * other->mass) / distanceCubed;

                Vector3 direction = (position - other->position).normalize();
                force += direction * forceMagnitude;
            }
        }

        acceleration = force / mass;
        velocity += acceleration * deltaTime;
        position += velocity * deltaTime;
    }
};
