## 🌌 Space Simulation Physics Engine Implementation

```cpp
// gravity_physics_engine.cpp
#include <cmath>
#include <vector>
#include <stdexcept>
#include <iostream>

namespace space_simulation {
    // Gravitational constant in SI units (m³·kg⁻¹·s⁻²)
    constexpr double G = 6.67408e-11;

    // Represents a celestial body
    struct CelestialBody {
        double mass;
        double position[3];  // x, y, z
        double velocity[3];  // vx, vy, vz
    };

    // Calculate gravitational force between two bodies
    inline double calculate_gravitational_force(double m1, double m2, double distance) {
        if (distance <= 0.0) {
            throw std::domain_error("Distance must be greater than zero.");
        }
        return (G * m1 * m2) / std::pow(distance, 3);
    }

    // Apply gravitational force vector between two bodies
    inline void apply_gravitational_force(CelestialBody& body1, CelestialBody& body2) {
        // Compute relative vector from body2 to body1
        double dx = body1.position[0] - body2.position[0];
        double dy = body1.position[1] - body2.position[1];
        double dz = body1.position[2] - body2.position[2];
        double distance_sq = dx*dx + dy*dy + dz*dz;
        double distance = std::sqrt(distance_sq);

        if (distance <= 0.0) {
            throw std::domain_error("Celestial bodies cannot occupy the same position.");
        }

        double force_mag = calculate_gravitational_force(body1.mass, body2.mass, distance);

        // Gravitational force vector on body1 (F = G*m1*m2/r³ * (r_vector))
        double force_x = (dx / distance) * force_mag;
        double force_y = (dy / distance) * force_mag;
        double force_z = (dz / distance) * force_mag;

        // Apply force to body1's acceleration (using F = ma)
        // Assuming standard gravitational force direction (body1 is pulled towards body2)
        body1.velocity[0] += force_x / body1.mass;
        body1.velocity[1] += force_y / body1.mass;
        body1.velocity[2] += force_z / body1.mass;

        // Apply equal and opposite force on body2
        body2.velocity[0] -= force_x / body2.mass;
        body2.velocity[1] -= force_y / body2.mass;
        body2.velocity[2] -= force_z / body2.mass;
    }

    // Update positions of all celestial bodies
    void update_positions(std::vector<CelestialBody>& bodies, double time_step) {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = 0; j < bodies.size(); ++j) {
                if (i != j) {
                    apply_gravitational_force(bodies[i], bodies[j]);
                }
            }

            // Update position using velocity
            bodies[i].position[0] += bodies[i].velocity[0] * time_step;
            bodies[i].position[1] += bodies[i].velocity[1] * time_step;
            bodies[i].position[2] += bodies[i].velocity[2] * time_step;
        }
    }
}
```

